const fs=require('fs');
const geo=JSON.parse(fs.readFileSync('public/assets/geo/omeco-barangays.geojson'));
// The geographic index was generated by validated point-in-polygon selection.
const ts=require('typescript'),vm=require('vm');
const text=fs.readFileSync('src/app/data/mock/geography.ts','utf8');
const sandbox={exports:{}};
vm.runInNewContext(ts.transpileModule(text,{compilerOptions:{module:ts.ModuleKind.CommonJS}}).outputText,sandbox);
const places=sandbox.exports.BARANGAYS;
const selected=[];for(const municipality of [...new Set(places.map(x=>x.municipality))])selected.push(...places.filter(x=>x.municipality===municipality).slice(0,3));
const categories=['Power interruption','Damaged power line','Low voltage','Transformer concern','Meter concern','Damaged pole'];
const descriptions=[['Walang kuryente sa aming lugar mula kaninang umaga. Maraming bahay ang apektado.','There has been no power in our neighborhood since this morning.'],['May nakalaylay na kawad malapit sa daan. Pakiinspeksyon po.','A damaged low-hanging line was observed near the road.'],['Mahina ang boltahe at kumikislap ang ilaw tuwing gabi.','Low voltage and flickering lights are affecting several homes.'],['May kakaibang ingay ang transformer malapit sa aming bahay.','The transformer is making an unusual sound near our street.'],['Pakiinspeksyon po ang metro sa aming bahay.','Please inspect the meter at our property.'],['Nakasandal ang poste matapos ang ulan. Kailangan ng inspeksyon.','A pole appears damaged after rain and needs inspection.']];
const records=Array.from({length:96},(_,i)=>{const g=selected[(i*7+Math.floor(i/11))%selected.length];const category=i%6;const resolved=i%4===0;const reported=new Date(Date.UTC(2026,10,7,18)-(i*2+(i%7))*86400000-(i%12)*3600000);const hours=2+(i%9)*.75;return {id:i<6?'OC-'+(2841-i):'OC-'+(2900+i),member:i===0?'Ana Mendoza':'Demo User '+(i%24+4),category:categories[category],priority:['Urgent','Critical','Routine','Urgent','Routine','Critical'][category],status:resolved?'Resolved':i%4===1?'Work in progress':i%4===2?'New':'Dispatched',location:g.barangay+', '+g.municipality,time:reported.toISOString().slice(0,16).replace('T',' ')+' UTC',reportedAt:reported.toISOString(),households:1+(i*13)%89,description:descriptions[category][i%2],language:i%2?'English':'Filipino',assignedCrew:i%4===2?'':'Line Crew '+String(i%4+1).padStart(2,'0'),municipality:g.municipality,barangay:g.barangay,barangayCode:g.code,coordinates:g.coordinates,simulated:true,classificationReviewed:i%5===0,priorityReviewed:i%7===0,...(resolved?{resolvedAt:new Date(+reported+hours*3600000).toISOString(),actualRepairHours:hours}:{})};});
const crews=Array.from({length:4},(_,i)=>{const g=selected[i*6];return{id:'crew-'+(i+1),name:'Line Crew '+String(i+1).padStart(2,'0'),expertise:['Overhead line','Transformer','Meter services','Pole restoration'][i],available:i%2===0,coordinates:g.coordinates,municipality:g.municipality};});
const users=Array.from({length:33},(_,i)=>({id:'u-'+(i+1),name:i===0?'Maria Reyes':i===1?'Ana Mendoza':i===2?'Jose Lim':'Demo User '+(i+1),email:i===0?'admin@omeco.demo':i===1?'member@omeco.demo':i===2?'staff@omeco.demo':'demo'+(i+1)+'@omeco.demo',role:i===0?'admin':i===2||i%7===0?'field-worker':'member',municipality:selected[i%selected.length].municipality,active:i%9!==8,joined:'2026-01-'+String(i%28+1).padStart(2,'0')}));
const audit=records.slice(0,15).map((r,i)=>({id:'seed-'+i,timestamp:r.reportedAt,actor:'Seeded demo dispatcher',action:['Complaint submission','Classification review','Priority override','Dispatch approval','Repair progress'][i%5],recordId:r.id,detail:'Seeded simulated activity for '+r.category,seeded:true}));
const models=[{id:'nlp',name:'Bilingual classification',method:'NLP classifier',required:'Labeled Filipino/English text, preprocessing, stratified evaluation'},{id:'priority',name:'Incident priority',method:'XGBoost-style demo',required:'Reviewed priority labels, leakage checks, SHAP/LIME verification'},{id:'temporal',name:'Temporal forecasting',method:'LSTM / ARIMA / SARIMA',required:'Time-ordered observations, rolling validation, seasonal coverage'},{id:'restoration',name:'Restoration duration',method:'Regression interface',required:'Verified repair timestamps, crew and severity factors, calibration'}].map(x=>({...x,ready:false,version:null}));
fs.writeFileSync('src/app/data/mock/admin-seed.ts',`import { OmecoCase } from '../../models/concern';\nimport { Crew, DemoUser, AuditEvent, ModelReadiness } from '../../models/admin';\nexport const INCIDENT_SEED: OmecoCase[] = ${JSON.stringify(records,null,2)};\nexport const CREW_SEED: Crew[] = ${JSON.stringify(crews,null,2)};\nexport const USER_SEED: DemoUser[] = ${JSON.stringify(users,null,2)};\nexport const AUDIT_SEED: AuditEvent[] = ${JSON.stringify(audit,null,2)};\nexport const MODEL_SEED: ModelReadiness[] = ${JSON.stringify(models,null,2)};\n`);
console.log('Prepared',records.length,'connected incidents,',crews.length,'crews,',users.length,'users in',new Set(records.map(x=>x.municipality)).size,'municipalities.');
